(() => {
'use strict';
const D = window.SHIJIAN_DATA;
if (!D) { document.getElementById('app').innerHTML='<p class="load-error">食材数据暂未加载，请刷新页面。</p>'; return; }
const DRAFT_KEY='shijian:draft:v1', KEY='shijian:v1', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=window.SHIJIAN_NUTRITION;
const I=Object.fromEntries(D.ingredients.map(i=>[i.id,i])), R=Object.fromEntries(D.recipes.map(r=>[r.id,r]));

const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/><path d="M9 21v-8h6v8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m4 0h2m-8 3h2"/>',book:'<path d="M12 5C9 3 5 3 2 4v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v15"/>',leaf:'<path d="M20 3C10 2 3 7 4 13s8 9 12 4c3-4 3-9 4-14Z"/><path d="M3 22 15 9"/>',spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3ZM20 2v4m-2-2h4"/>',bag:'<path d="M5 7h14l2 14H3ZM8 8V6a4 4 0 0 1 8 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 11-2l3 7M4 12l3 7a7 7 0 0 0 11-2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M20.5 14.5A9 9 0 0 1 9.5 3.5a9 9 0 1 0 11 11Z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 3 2 3 3-1 3 2 3-2 3 1 2-3-1-3 2-2-2-3-3-1-1-3Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',people:'<circle cx="8" cy="7" r="3"/><path d="M2 21v-3a6 6 0 0 1 12 0v3m3-17a3 3 0 0 1 0 6m0 5a5 5 0 0 1 5 5v1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',bowl:'<path d="M3 11h18c-1 6-4 9-9 9s-8-3-9-9ZM7 7c0-3 3-3 3-6m4 6c0-3 3-3 3-6M7 22h10"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
const icon=(n,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.leaf}</svg>`;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const addDate=(d,n)=>{const a=new Date(d+'T12:00:00');a.setDate(a.getDate()+n);return `${a.getFullYear()}-${String(a.getMonth()+1).padStart(2,'0')}-${String(a.getDate()).padStart(2,'0')}`;};
const dateText=(d,long=false)=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',...(long?{weekday:'long'}:{})}).format(new Date(d+'T12:00:00'));
const weekday=d=>['周日','周一','周二','周三','周四','周五','周六'][new Date(d+'T12:00:00').getDay()];
const defaultState=()=>({version:1,plans:[],favorites:[],checked:{},pantry:{},budget:{},preferences:{defaultMealMode:'both'}});
const validMode=(mode,fallback='both')=>{if(mode==null)return fallback;if(!['both','dinner'].includes(mode))throw Error('餐次设置无效');return mode;};
const mealKinds=scope=>N.kinds(typeof scope==='string'?scope:scope?.mealMode||'both');
const scopeLabel=scope=>mealKinds(scope).length===1?'晚餐':'午餐＋晚餐';
function modeControl(mode,action,caption='安排哪些正餐？'){return `<fieldset class="meal-mode-control"><legend>${caption}</legend><div class="meal-mode-segment" role="radiogroup" aria-label="${caption}">${[['both','午餐＋晚餐'],['dinner','只安排晚餐']].map(([id,label])=>`<button role="radio" aria-checked="${mode===id}" class="${mode===id?'active':''}" data-action="${action}" data-mode="${id}">${icon(id==='both'?'sun':'moon')}${label}<span class="mode-check" ${mode===id?'':'hidden'}>${icon('check')}</span></button>`).join('')}</div></fieldset>`;}
function validState(v){
 if(!v||v.version!==1||!Array.isArray(v.plans)||v.plans.length>100)throw Error('文件格式不正确');
 const dates=new Set(),ids=new Set();
 const cleanMap=(value,kind)=>{const out=Object.create(null);if(!value||typeof value!=='object'||Array.isArray(value))return out;for(const [key,row] of Object.entries(value)){if(!/^[\w-]{1,80}$/.test(key)||['__proto__','constructor','prototype'].includes(key))continue;if(kind==='budget'){if(typeof row==='number'&&Number.isFinite(row)&&row>=0&&row<=99999)out[key]=row;}else if(row&&typeof row==='object'&&!Array.isArray(row)){const entries=Object.create(null);for(const [id,checked]of Object.entries(row))if(Object.hasOwn(I,id)&&typeof checked==='boolean')entries[id]=checked;out[key]=entries;}}return out;};
 const plans=v.plans.map(p=>{if(!p||typeof p.id!=='string'||!/^[\w-]{1,80}$/.test(p.id)||['__proto__','constructor','prototype'].includes(p.id)||ids.has(p.id)||typeof p.start!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(p.start)||Number.isNaN(new Date(p.start+'T12:00:00').getTime())||addDate(p.start,0)!==p.start||!Array.isArray(p.days)||p.days.length<3||p.days.length>7)throw Error('菜单日期或格式不正确');ids.add(p.id);const days=p.days.map((d,j)=>{const date=addDate(p.start,j);if(dates.has(date))throw Error('菜单日期重叠');dates.add(date);const mode=validMode(p.mealMode),clean={};for(const k of mealKinds(mode)){clean[k]={};for(const slot of ['main','veg','staple']){const id=d?.[k]?.[slot];if(typeof id!=='string'||!Object.hasOwn(R,id)||R[id].type!==slot)throw Error('菜单中的菜品不可用');clean[k][slot]=id;}if(d[k].soup){const id=d[k].soup;if(typeof id!=='string'||!Object.hasOwn(R,id)||R[id].type!=='soup')throw Error('汤羹数据不可用');clean[k].soup=id;}}if(typeof d?.fruit!=='string'||!Object.hasOwn(I,d.fruit)||I[d.fruit].category!=='fruit')throw Error('水果数据不可用');clean.fruit=d.fruit;return clean;});return {id:p.id,start:p.start,days,mealMode:validMode(p.mealMode),created:Number.isFinite(p.created)?p.created:Date.now()};});
 return {version:1,plans,favorites:Array.isArray(v.favorites)?[...new Set(v.favorites.filter(x=>typeof x==='string'&&Object.hasOwn(R,x)))]:[],checked:cleanMap(v.checked,'check'),pantry:cleanMap(v.pantry,'check'),budget:cleanMap(v.budget,'budget'),preferences:{defaultMealMode:validMode(v.preferences?.defaultMealMode)}};
}
let state=defaultState(),storageError=false,rawBackup=null;
try{const raw=localStorage.getItem(KEY);if(raw){rawBackup=raw;state=validState(JSON.parse(raw));rawBackup=null;}}catch(e){storageError=true;}
let view='home',activePlan=null,dayIndex=0,recipeFilter='all',recipeQuery='',recipeSort='recommended',ingredientFilter='all',ingredientQuery='',modalBack=null,wizard=null,swapContext=null,focusBefore=null,toastTimer,modalHistory=[],pickerQuery='',photoMode='cooked',draft=null,fruitApplyAll=false;
const navs=[['home','home','今日食间'],['plans','calendar','我的菜单'],['recipes','book','灵感厨房'],['ingredients','leaf','食材百科'],['science','spark','好好吃的科学'],['shopping','bag','买菜清单']];
function syncBadge(){const badge=$('.local-badge');if(badge)badge.innerHTML=`<i></i>${storageError?'需要备份':'已保存在本机'}`;}
function save(){try{if(rawBackup){localStorage.setItem(KEY+':recovery',rawBackup);rawBackup=null;}localStorage.setItem(KEY,JSON.stringify(state));storageError=false;syncBadge();return true;}catch{storageError=true;syncBadge();toast('浏览器储存不可用，请导出菜单备份');return false;}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function pickPlan(){const t=today();return state.plans.find(p=>p.start<=t&&addDate(p.start,p.days.length-1)>=t)||state.plans.filter(p=>p.start>t).sort((a,b)=>a.start.localeCompare(b.start))[0]||null;}
function getPlan(){return state.plans.find(p=>p.id===activePlan)||pickPlan();}
function sprite(v,l){const [aw,ah]=v.sourceSize||[v.columns*100,v.rows*100];const rect=v.sourceRect||[v.index%v.columns*aw/v.columns,Math.floor(v.index/v.columns)*ah/v.rows,aw/v.columns,ah/v.rows];const [x,y,w,h]=rect,size=Math.max(w,h),bounds=l.bounds||[0,0,w,h],scale=l.scale||1,cx=(bounds[0]+bounds[2])/2,cy=(bounds[1]+bounds[3])/2;return `<svg class="sprite-svg" viewBox="0 0 ${size} ${size}" aria-hidden="true" preserveAspectRatio="xMidYMid meet"><g transform="translate(${size/2} ${size/2}) scale(${scale})"><svg x="${-cx}" y="${-cy}" width="${w}" height="${h}" viewBox="${x} ${y} ${w} ${h}" overflow="hidden"><image href="assets/${esc(v.file)}" width="${aw}" height="${ah}"/></svg></g></svg>`;}
function picture(id,cl=''){const i=I[id],v=window.SHIJIAN_VISUALS?.ingredients[id];if(!v)return `<span class="food-photo food-fallback ${cl}" role="img" aria-label="${esc(i?.name||id)}">${icon('leaf')}</span>`;const l=window.SHIJIAN_ASSET_LAYOUT?.ingredients?.[id]||{};return `<span class="food-photo ${cl} sprite-framed" role="img" aria-label="${esc(i?.name||id)}">${sprite(v,l)}</span>`;}
function primaryId(r){return r.ingredients.find(x=>!['seasoning','grain'].includes(I[x.id]?.category))?.id||r.ingredients[0].id;}
function rawRecipeVisual(r,cl=''){const ids=r.ingredients.filter(x=>I[x.id]&&I[x.id].category!=='seasoning').slice(0,3).map(x=>x.id);return `<div class="recipe-art ${cl}" style="--card-tint:${esc(r.color||'#edf1e8')}">${ids.map((id,i)=>`<button class="raw-ingredient-button raw-${i}" data-action="ingredient" data-id="${id}" aria-label="认识${esc(I[id].name)}">${picture(id)}</button>`).join('')}<span class="art-leaf">${icon('leaf')}</span></div>`;}
function cooked(id,cl=''){const r=R[id],v=window.SHIJIAN_VISUALS?.recipes[id];if(!r||!v)return `<span class="cooked-empty ${cl}">${icon('bowl')}</span>`;const l=window.SHIJIAN_ASSET_LAYOUT?.recipes?.[id]||{};return `<span class="cooked-food sprite-framed ${cl}" role="img" aria-label="${esc(r.name)}成品示意">${sprite(v,l)}</span>`;}
let sceneIndex=0;
function plateVisual(m,cl='',interactive=true){const selected=['main','veg','staple','soup'].filter(s=>R[m[s]]);return `<div class="meal-scene ${cl}" data-scene-key="meal-${++sceneIndex}" data-meal="${esc(JSON.stringify(m))}" data-interactive="${interactive}" aria-label="${selected.map(s=>R[m[s]].name).join('、')||'待搭配'}的立体餐桌"><div class="scene-loading">${icon('bowl')}<span>正在布置餐桌…</span></div><div class="scene-photo-fallback" hidden>${selected.map(s=>`<button data-action="recipe" data-id="${m[s]}">${cooked(m[s])}<span>${esc(R[m[s]].name)}</span></button>`).join('')||'<p>从下方选一道你喜欢的菜</p>'}</div></div>`;}
function recipeVisual(r,cl=''){return `<div class="recipe-art finished-art ${cl}" style="--card-tint:${esc(r.color||'#edf1e8')}">${cooked(r.id,'single-cooked')}<span class="finished-caption">成品灵感</span></div>`;}
function ingredientChips(r,limit=4){return `<div class="ingredient-chips">${r.ingredients.filter(x=>I[x.id]?.category!=='seasoning').slice(0,limit).map(x=>`<button data-action="ingredient" data-id="${x.id}" aria-label="认识${esc(I[x.id].name)}">${picture(x.id)}${esc(I[x.id].name)}</button>`).join('')}</div>`;}
function validDraft(v){if(!v||typeof v.start!=='string'||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(v.start)||addDate(v.start,0)!==v.start||!Array.isArray(v.days)||v.days.length<3||v.days.length>7)throw Error('草稿格式无效');const days=v.days.map(d=>{const result={fruit:null,lunch:{},dinner:{}};for(const kind of ['lunch','dinner'])for(const slot of ['main','veg','staple','soup']){const id=d?.[kind]?.[slot];if(id&&(!Object.hasOwn(R,id)||R[id].type!==slot))throw Error('草稿菜品无效');if(slot!=='soup'||id)result[kind][slot]=id||null;}if(d.fruit){if(!Object.hasOwn(I,d.fruit)||I[d.fruit].category!=='fruit')throw Error('草稿水果无效');result.fruit=d.fruit;}return result;});return {start:v.start,count:days.length,days,index:Math.min(Math.max(Math.floor(Number(v.index)||0),0),days.length-1),editId:state.plans.some(p=>p.id===v.editId)?v.editId:null,mealMode:validMode(v.mealMode)};}
try{const raw=localStorage.getItem(DRAFT_KEY);if(raw)draft=validDraft(JSON.parse(raw));}catch{}
function saveDraft(){if(wizard?.days){draft=wizard;try{localStorage.setItem(DRAFT_KEY,JSON.stringify(draft));}catch{toast('草稿暂无法保存，请保持当前页面');}}}
function draftCompleteDay(d,scope=wizard||draft){return mealKinds(scope).every(k=>['main','veg','staple'].every(s=>Object.hasOwn(R,d[k]?.[s])))&&!!I[d.fruit];}
function missingDraft(w){return w.days.reduce((n,d)=>n+mealKinds(w).reduce((sum,k)=>sum+['main','veg','staple'].filter(s=>!d[k][s]).length,0)+(d.fruit?0:1),0);}
function resumeDraftBanner(){return draft?`<div class="resume-draft"><span>${icon('calendar')}</span><div><strong>上次的餐桌灵感还在这里</strong><p>${dateText(draft.start)}起的 ${draft.days.length} 天草稿，继续选好喜欢的菜与水果。</p></div><button class="text-link" data-action="resume-draft">继续搭配 ${icon('arrow')}</button></div>`:'';}

const tags=r=>(r.tags||[]).slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join('');
function recipeCard(r){return `<article class="recipe-card"><button class="card-image-button" data-action="recipe" data-id="${esc(r.id)}" aria-label="查看${esc(r.name)}">${recipeVisual(r)}</button><button class="favorite ${state.favorites.includes(r.id)?'is-favorite':''}" data-action="favorite" data-id="${esc(r.id)}" aria-label="${state.favorites.includes(r.id)?'取消收藏':'收藏'}${esc(r.name)}" aria-pressed="${state.favorites.includes(r.id)}">${icon('heart')}</button><div class="recipe-card-body"><button class="title-button" data-action="recipe" data-id="${esc(r.id)}">${esc(r.name)}${icon('chevron')}</button><p>${esc(r.benefit)}</p><div class="tags">${tags(r)}</div>${ingredientChips(r,3)}</div></article>`;}
function sectionHead(title,sub,link,label){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<button class="text-link" data-action="navigate" data-view="${link}">${label||'查看全部'}${icon('arrow')}</button>`:''}</div>`;}
function render(motion='page'){window.SHJ_SCENE?.disposeAll();sceneIndex=0;const oldScroll=$('.day-strip')?.scrollLeft||0;const p=getPlan();if(p)dayIndex=Math.min(dayIndex,p.days.length-1);const renderScope=view==='builder'?(wizard||draft):p||state.preferences.defaultMealMode;const markup=`<div class="app-shell"><aside class="sidebar"><a href="#home" class="brand" data-action="navigate" data-view="home"><span class="brand-mark">${icon('bowl')}</span><span>食间<small>SHI JIAN</small></span></a><div class="nav-caption">我的饮食日常</div><nav aria-label="主导航">${navs.map(([id,ic,l])=>`<button class="nav-item ${(view==='builder'?'plans':view)===id?'active':''}" data-action="navigate" data-view="${id}" ${(view==='builder'?'plans':view)===id?'aria-current="page"':''}>${icon(ic)}<span>${l}</span>${id==='plans'&&state.plans.length?`<span class="nav-count">${state.plans.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-note"><span class="tiny-sprout">${icon('leaf')}</span><p>饭要好好吃，<br>日子要慢慢过。</p><small>川渝家常 · 两人食</small></div><button class="settings-link" data-action="settings">${icon('settings')}本地数据与设置</button></aside><div class="main-shell"><header class="topbar"><div class="mobile-brand"><span class="brand-mark">${icon('bowl')}</span>食间</div><div class="topbar-greeting">${dateText(today())} <span>·</span> 今天也要好好吃饭</div><div class="topbar-right"><button class="local-badge" data-action="settings" aria-label="本地数据与设置"><i></i> ${storageError?'需要备份':'已保存在本机'}</button><span class="people-avatar" aria-label="两人家庭">${icon('people')}</span></div></header><main id="main-content" tabindex="-1">${storageError?'<div class="storage-warning">本地数据读取或保存失败。当前可继续使用，请在设置中导出备份；读取失败的原始记录会在保存新内容前保留恢复副本，可在设置中下载。</div>':''}${view==='builder'?builder():view==='home'?home(p):view==='plans'?plans():view==='recipes'?recipes():view==='ingredients'?ingredients():view==='science'?science():shopping(p)}</main><footer class="page-footer"><span>食间 SHI JIAN</span><span>把日子过成喜欢的味道 <i>✦</i></span><span>仅规划${scopeLabel(renderScope)}与水果</span></footer><nav class="mobile-nav" aria-label="手机导航">${navs.map(([id,ic,l])=>`<button data-action="navigate" data-view="${id}" class="${(view==='builder'?'plans':view)===id?'active':''}">${icon(ic)}<span>${id==='science'?'科学':id==='recipes'?'灵感':id==='shopping'?'买菜':id==='ingredients'?'食材':id==='plans'?'菜单':'今日'}</span></button>`).join('')}</nav></div></div>`;if(!$('.app-shell'))$('#app').innerHTML=markup;else{const template=document.createElement('template');template.innerHTML=markup;$('#main-content').replaceChildren(...template.content.querySelector('#main-content').childNodes);document.querySelectorAll('[data-action="navigate"]').forEach(el=>{const selected=el.dataset.view===(view==='builder'?'plans':view);if(el.classList.contains('nav-item')||el.closest('.mobile-nav')){el.classList.toggle('active',selected);if(selected)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');}});const planNav=$('.nav-item[data-view="plans"]');if(planNav){const currentCount=planNav.querySelector('.nav-count');if(state.plans.length){if(currentCount)currentCount.textContent=state.plans.length;else planNav.insertAdjacentHTML('beforeend',`<span class="nav-count">${state.plans.length}</span>`);}else currentCount?.remove();}}
 if($('.day-strip'))$('.day-strip').scrollLeft=oldScroll;const footerScope=$('.page-footer>span:last-child');if(footerScope)footerScope.textContent=`仅规划${scopeLabel(renderScope)}与水果`;syncBadge();
 window.SHJ_SCENE?.mountAll();

}
function home(p){return `<div class="page-intro"><div><span class="eyebrow">A LITTLE PLAN, A LOVELY DAY</span><h1>两个人，好好吃饭<span class="heading-spark">✳</span></h1><p>寻常的食材，也能搭出认真生活的味道。</p></div><span class="household-chip">${icon('people')} 两人食 · 川渝家常</span></div>${resumeDraftBanner()}${p?plannedHome(p):emptyHome()}<div class="home-lower"><section class="balance-card"><div><span class="eyebrow">刚刚好的搭配</span><h3>一餐的平衡，<br>不用复杂计算。</h3><p>用餐盘比例做起点，<br>再根据饥饿感与活动量调整。</p><button class="text-link" data-action="science-detail" data-id="${esc(D.science[0]?.id)}">为什么这样搭 ${icon('arrow')}</button></div><div class="plate-guide" aria-label="餐盘参考：蔬菜约一半，主食与蛋白质菜各约四分之一"><div class="plate-ring"><span class="plate-veg">蔬菜<small>约 ½</small></span><span class="plate-protein">蛋白质<small>约 ¼</small></span><span class="plate-grain">主食<small>约 ¼</small></span><i></i></div></div></section><section class="science-teaser"><span class="science-teaser-icon">${icon('spark')}</span><span class="eyebrow">今天的一点小知识</span><h3>减脂，也可以<br>安心吃米饭。</h3><p>一碗饭不是敌人。让杂粮、蔬菜和蛋白质一起加入餐桌，才是更长久的吃法。</p><button class="text-link" data-action="navigate" data-view="science">和食间一起了解 ${icon('arrow')}</button><span class="rice-decoration">${picture('rice')}</span></section></div>`;}
function emptyHome(){const feature=D.recipes.filter(r=>r.type==='main').slice(0,3);return `<section class="hero empty-hero"><div class="hero-copy"><span class="hero-kicker"><i></i> 为两个人，留一点生活的滋味</span><h2>好好吃饭，<br>从喜欢的<span>一餐开始。</span></h2><p>米饭照常吃，川菜照常香。<br>把蔬菜、蛋白质和主食，搭成你们的日常。</p><button class="button primary" data-action="new-plan">搭配我的第一份菜单 ${icon('arrow')}</button><div class="hero-footnote"><span>${icon('calendar')} 3–7 天自由安排</span><span>${icon('leaf')} 水果自己选</span></div></div><div class="hero-table"><div class="studio-caption"><span>THE EVERYDAY TABLE</span><span>两人食的餐桌灵感</span></div>${plateVisual({main:'pepperPork',veg:'garlicBroccoli',staple:'oatRice'},'hero-scene')}<div class="studio-bottom"><span>${icon('heart')} 日常的烟火，也可以很轻盈</span><span>拖动餐盘，换个角度看看</span></div></div></section><section class="inspiration-section">${sectionHead('今天，想吃点什么？','熟悉的川渝味道，一道一道认真搭配。','recipes','逛逛灵感厨房')}<div class="recipe-grid home-recipe-grid">${feature.map(recipeCard).join('')}</div></section>`;}
function plannedHome(p){const d=p.days[dayIndex],date=addDate(p.start,dayIndex);return `<section class="planned-banner"><div><span class="hero-kicker"><i></i> ${p.start>today()?'下一段好好吃饭的日子':'你的饮食计划已就位'}</span><h2>${p.start>today()?'期待下一餐的幸福。':'今天吃什么，心里有数。'}</h2><p>${dateText(p.start)} — ${dateText(addDate(p.start,p.days.length-1))} <span>·</span> ${p.days.length} 天两人食 · ${scopeLabel(p)}</p></div><div class="banner-calendar" aria-hidden="true"><small>${weekday(date)}</small><strong>${new Date(date+'T12:00:00').getDate()}</strong><span>${new Date(date+'T12:00:00').getMonth()+1} 月的餐桌</span></div><div class="plan-banner-actions"><button class="button secondary" data-action="edit-plan">${icon('calendar')} 编辑这一周期</button><button class="text-link" data-action="new-plan" data-future="true">${icon('plus')} 规划下一周期</button></div></section><section class="daily-plan">${sectionHead(`${dayIndex===0?'第一':`第${dayIndex+1}`}天的餐桌`,'搭配已准备好，随时换成你们更想吃的。','shopping','看看需要买什么')}<div class="day-strip" role="tablist" aria-label="选择菜单日期">${p.days.map((_,i)=>`<button role="tab" aria-selected="${i===dayIndex}" class="day-tab ${i===dayIndex?'selected':''}" data-action="day" data-index="${i}"><span>${weekday(addDate(p.start,i))}${addDate(p.start,i)===today()?'<i>今天</i>':''}</span><strong>${dateText(addDate(p.start,i))}</strong></button>`).join('')}</div><div class="meal-grid ${p.mealMode==='dinner'?'dinner-only':''}" data-meal-mode="${p.mealMode||'both'}">${mealKinds(p).map(kind=>mealCard(kind,d[kind],date)).join('')}<article class="fruit-card"><div class="meal-title"><span class="meal-icon fruit-icon">${icon('leaf')}</span><div><h3>今日水果</h3><span>让日常多一点清甜</span></div><button class="fruit-select-trigger" data-action="swap-fruit">自选水果 ${icon('down')}</button></div><button class="fruit-display" data-action="ingredient" data-id="${d.fruit}" aria-label="认识${esc(I[d.fruit]?.name)}">${picture(d.fruit)}</button><h3>${esc(I[d.fruit]?.name)}</h3><p>${esc(I[d.fruit]?.benefit)}</p><div class="fruit-note">水果安排在两餐之间，<br>也记得吃蔬菜哦。</div><button class="text-link" data-action="ingredient" data-id="${esc(d.fruit)}">认识这份水果 ${icon('arrow')}</button></article></div>${dayNutrition(d,p)}</section><div class="future-prompt"><span>${icon('calendar')}</span><div><h3>给未来的餐桌，留一点期待</h3><p>这一轮结束后，再试试新搭配。食间会保留每一份计划。</p></div><button class="text-link" data-action="new-plan" data-future="true">添加下一周期 ${icon('plus')}</button></div>`;}
function gramText(n){return Number(n.toFixed(1)).toString();}
function nutritionValues(n){return `<div class="nutrition-values">${[['kcal','kcal 能量'],['protein','g 蛋白质'],['fat','g 脂肪'],['carbs','g 碳水'],['fiber','g 膳食纤维']].map(([k,label])=>`<span><strong>${gramText(n[k])}</strong>${label}</span>`).join('')}</div>`;}
function gramsTable(rows){return `<div class="gram-table-scroll"><table class="gram-table"><thead><tr><th>食材</th><th>双人原料</th><th>每人均分</th></tr></thead><tbody>${rows.map(row=>`<tr><td><button class="weight-ingredient" data-action="ingredient" data-id="${row.id}">${esc(row.name)}</button><small>${row.basis}</small></td><td>${gramText(row.g)} g</td><td>${gramText(row.perPersonG)} g</td></tr>`).join('')}</tbody></table></div>`;}
function dayNutrition(d,p){const n=N.day(d,p.mealMode||'both',2);return `<details class="day-nutrition"><summary><span>${icon('leaf')} ${scopeLabel(p)}与水果 · 原料克重和营养估算</span>${icon('down')}</summary><p>以下按 <strong>2 人的${scopeLabel(p)}与水果</strong>计算。所有所选菜品按双人配方汇总，水果按每人 200 g 可食部计入；下方明确区分双人总量和每人均分参考。</p><h4>每人均分参考（双人配方 ÷ 2）</h4>${nutritionValues(n.perPerson)}<details class="pair-total"><summary>查看双人合计 ${icon('down')}</summary>${nutritionValues(n.total)}</details><h4>本日双人原料克重</h4>${gramsTable(n.rows)}<small>计算公式：每种原料的每 100 g 营养参考值 × 可食部原料克数 ÷ 100，再相加；单人参考值 = 双人合计 ÷ 2。米按煮前重量、干木耳按干重，熟花生按直接食用重量记录，不把烹调加水当作额外能量。以上不含${p.mealMode==='dinner'?'午餐、':''}早餐、饮品和零食，也不是实际摄入测量或全天达标判断。${esc(D.meta.dataNote)}</small></details>`;}

function mealCard(kind,m,date){return `<article class="meal-card"><div class="meal-title"><span class="meal-icon ${kind}">${icon(kind==='lunch'?'sun':'moon')}</span><div><h3>${kind==='lunch'?'午餐':'晚餐'}</h3><span>${kind==='lunch'?'把喜欢的菜，盛在同一只盘子里':'用一盘家常味，收好这一天'}</span></div><button class="meal-edit-pill" data-action="swap" data-kind="${kind}" data-slot="main">选菜 ${icon('plus')}</button></div><div class="meal-plated-stage">${plateVisual(m)}<span class="plate-note">${icon('bowl')} 立体搭配示意 · 拖动旋转，点击菜品看做法</span></div>${['main','veg','staple',...(m.soup?['soup']:[])].map((slot,i)=>{const r=R[m[slot]];return `<div class="meal-dish"><button class="dish-photo-button" data-action="recipe" data-id="${r.id}" aria-label="查看${esc(r.name)}">${cooked(r.id,'dish-photo')}</button><button class="dish-name" data-action="recipe" data-id="${r.id}"><small>${['蛋白质菜','蔬菜','主食','汤羹'][i]}</small><strong>${esc(r.name)}</strong></button><button class="swap-button" data-action="swap" data-kind="${kind}" data-slot="${slot}" aria-label="替换${esc(r.name)}">${icon('refresh')}</button></div>`;}).join('')}<div class="meal-ingredients-label">点击食材，认识这一餐</div>${ingredientChips(R[m.main],4)}<button class="meal-soup-link" data-action="${m.soup?'remove-soup':'swap'}" data-kind="${kind}" data-slot="soup">${icon(m.soup?'close':'plus')}${m.soup?'去掉这道汤':'想喝汤？加一道家常汤'}</button></article>`;}

function plans(){const sorted=[...state.plans].sort((a,b)=>b.start.localeCompare(a.start));return `${pageTitle('我的菜单','把接下来的日子，过得有滋有味。',`<button class="button primary" data-action="new-plan">${icon('plus')} 新建饮食计划</button>`)}${!sorted.length?emptyState('calendar','餐桌还在等你安排','选一个开始日期，让食间陪你计划接下来的几天。','new-plan','开始第一份计划'):`<div class="plans-grid">${sorted.map(p=>{const end=addDate(p.start,p.days.length-1),status=end<today()?'已结束':p.start>today()?'即将开始':'进行中';return `<article class="plan-card"><div class="plan-card-top"><span class="plan-status ${status==='进行中'?'current':''}">${status}</span><span>${p.days.length} 天 · 两人食 · ${scopeLabel(p)}</span></div><div class="plan-foods">${[primaryId(R[p.days[0][mealKinds(p)[0]].main]),primaryId(R[p.days[0][mealKinds(p)[0]].veg]),p.days[0].fruit].map(id=>picture(id)).join('')}</div><h3>${dateText(p.start)} — ${dateText(end)}</h3><p>${esc(R[p.days[0][mealKinds(p)[0]].main].name)}等 ${p.days.length} 天${scopeLabel(p)}搭配</p><div class="plan-actions"><button class="text-link" data-action="open-plan" data-id="${esc(p.id)}">查看与调整 ${icon('arrow')}</button><button class="icon-button" data-action="delete-plan" data-id="${esc(p.id)}" aria-label="删除${esc(dateText(p.start))}的计划">${icon('trash')}</button></div></article>`;}).join('')}</div>`}<div class="gentle-note">${icon('info')} 计划按日期保存；为未来安排新菜单，不会覆盖之前的记录。</div>`;}
function pageTitle(title,sub,action=''){return `<div class="page-intro"><div><span class="eyebrow">SHI JIAN · EVERYDAY KITCHEN</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function emptyState(ic,title,sub,action,label){return `<div class="empty-state"><span class="empty-icon">${icon(ic)}</span><h2>${title}</h2><p>${sub}</p><button class="button primary" data-action="${action}">${label} ${icon('arrow')}</button></div>`;}
function sortControl(){return `<div class="custom-select"><button class="sort-trigger" data-action="toggle-sort" aria-expanded="false">${icon('down')} ${recipeSort==='ingredients'?'食材较少':recipeSort==='name'?'菜名排序':'食间推荐'} ${icon('down')}</button><div class="select-options" hidden role="menu">${[['recommended','食间推荐'],['ingredients','食材较少'],['name','菜名排序']].map(([id,l])=>`<button role="menuitemradio" aria-checked="${recipeSort===id}" data-action="sort" data-sort="${id}">${l}${recipeSort===id?icon('check'):''}</button>`).join('')}</div></div>`;}
function recipes(){let rs=D.recipes.filter(r=>(recipeFilter==='all'||(recipeFilter==='favorites'?state.favorites.includes(r.id):r.type===recipeFilter))&&(!recipeQuery||[r.name,...r.ingredients.map(x=>I[x.id]?.name),...(r.tags||[])].join(' ').includes(recipeQuery)));if(recipeSort==='ingredients')rs.sort((a,b)=>a.ingredients.length-b.ingredients.length);if(recipeSort==='name')rs.sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'));return `${pageTitle('灵感厨房','熟悉的家常菜，搭配一点新灵感。',`<button class="button secondary" data-action="new-plan">${icon('calendar')} 去安排菜单</button>`)}<div class="filter-toolbar">${sortControl()}<div class="filter-pills" aria-label="菜谱分类">${[['all','全部菜谱'],['main','蛋白质菜'],['veg','蔬菜'],['soup','汤羹'],['staple','饭与粥'],['favorites','我的收藏']].map(([id,l])=>`<button class="pill ${recipeFilter===id?'active':''}" data-action="recipe-filter" data-filter="${id}" aria-pressed="${recipeFilter===id}">${l}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="recipe-search" type="search" placeholder="搜索菜名或食材" aria-label="搜索菜谱" value="${esc(recipeQuery)}"></label></div><div class="result-caption"><span>${rs.length} 道家常灵感</span><span>AI 成品示意 · 点击食材了解搭配</span></div><div class="recipe-grid">${rs.map(recipeCard).join('')}</div>${!rs.length?'<div class="no-results">没有找到这道菜，试试“番茄”或“豆腐”。</div>':''}`;}
function ingredients(){const rows=D.ingredients.filter(i=>(ingredientFilter==='all'||i.category===ingredientFilter)&&(!ingredientQuery||[i.name,...(i.alias||[])].join(' ').includes(ingredientQuery)));return `${pageTitle('食材百科','认识具体食材，也认识它们在一餐里的位置。')}<div class="ingredients-banner"><span>${icon('leaf')}</span><div><h3>一样叫“茄子”，也要认认真真区分。</h3><p>这里使用川渝菜场常见的具体品种。别名方便搜索，品种不会混为一谈。</p></div>${picture('eggplant')}</div><div class="filter-toolbar"><div class="filter-pills">${[['all','全部食材'],['grain','主食'],['protein','蛋白质'],['vegetable','蔬菜'],['fruit','水果'],['seasoning','调味']].map(([id,l])=>`<button class="pill ${ingredientFilter===id?'active':''}" data-action="ingredient-filter" data-filter="${id}">${l}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="ingredient-search" type="search" placeholder="食材名称或本地叫法" aria-label="搜索食材" value="${esc(ingredientQuery)}"></label></div><div class="result-caption"><span>${rows.length} 种川渝常见食材</span><span>按具体品种收录 · 点开认识它</span></div><div class="ingredient-grid">${rows.map(i=>`<button class="ingredient-card" data-action="ingredient" data-id="${esc(i.id)}"><span class="ingredient-gallery-art">${picture(i.id)}</span><div class="ingredient-card-copy"><span class="ingredient-category">${categoryName(i.category)}</span><h3>${esc(i.name)}</h3><p>${esc(i.role)}</p></div>${icon('chevron')}</button>`).join('')}</div>${!rows.length?'<div class="no-results">暂未收录这类食材，试试本地常用名称。</div>':''}`;}
const categoryName=c=>({grain:'主食与杂粮',protein:'蛋白质食材',vegetable:'新鲜蔬菜',fruit:'今日水果',seasoning:'厨房调味'}[c]||c);
function science(){return `${pageTitle('好好吃的科学','有依据的饮食知识，变成能用在今天的建议。')}<section class="science-hero"><div><span class="eyebrow">温和，也有依据</span><h2>好好吃饭，<br>是照顾自己的长期主义。</h2><p>保持正常饮食，理解能量平衡。<br>让选择更轻松，让生活更有滋味。</p></div><div class="science-foods">${picture('apple')}${picture('broccoli')}${picture('rice')}</div></section><div class="science-grid">${D.science.map((s,i)=>`<button class="science-card" data-action="science-detail" data-id="${esc(s.id)}"><span class="science-number">0${i+1}</span><span class="science-topic">${['科学减脂','米饭与杂粮','蛋白质','蔬菜与纤维','日常水果','备菜与安全'][i]||'科学饮食'}</span><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p><span class="text-link">慢慢了解 ${icon('arrow')}</span></button>`).join('')}</div><div class="source-note">${icon('book')}<div><h3>把依据放在你看得见的地方</h3><p>科普参考中国居民膳食指南（2022）及 WHO 等资料；每篇内容均附原始来源。餐盘比例是实用搭配参考，不是个体医疗处方。</p><button class="text-link" data-action="sources">查看内容来源与数据说明 ${icon('arrow')}</button></div></div>`;}
function shopping(p){if(!p)return `${pageTitle('买菜清单','有了菜单，买菜也能更从容。')}${emptyState('bag','先安排餐桌，再准备食材','选好要安排的正餐与水果，这里会自动整理要用到的食材。','new-plan','去规划菜单')}`;const amounts=aggregate(p),checked=state.checked[p.id]||{},pantry=state.pantry[p.id]||{},count=Object.keys(amounts).filter(id=>!pantry[id]).length,done=Object.keys(amounts).filter(id=>checked[id]&&!pantry[id]).length;return `${pageTitle('买菜清单','只看需要什么，让熟悉厨房的你自由掌握。',`<button class="button secondary" data-action="copy-shopping">${icon('download')} 复制清单</button>`)}<div class="shopping-summary"><div><span class="eyebrow">这份计划的采购准备</span><h2>${dateText(p.start)} — ${dateText(addDate(p.start,p.days.length-1))}</h2><p>${p.days.length} 天${scopeLabel(p)}与水果 · 两人食</p></div><div class="shopping-progress"><strong>${done}<span> / ${count}</span></strong><p>种食材已准备</p><div class="progress-track"><i style="width:${count?done/count*100:100}%"></i></div></div></div><div class="shopping-layout"><div class="shopping-groups">${['vegetable','protein','grain','fruit','seasoning'].map(c=>{const ids=Object.keys(amounts).filter(id=>I[id].category===c);return ids.length?`<section class="shopping-group"><h3>${categoryName(c)}<span>${ids.length} 种</span></h3>${ids.map(id=>`<div class="shopping-row ${checked[id]?'done':''} ${pantry[id]?'in-pantry':''}"><button class="check-control ${checked[id]?'checked':''}" data-action="shopping-check" data-id="${id}" role="checkbox" aria-checked="${!!checked[id]}" aria-label="已准备${esc(I[id].name)}">${checked[id]?icon('check'):''}</button><button class="shopping-photo-button" data-action="ingredient" data-id="${id}" aria-label="认识${esc(I[id].name)}">${picture(id)}</button><button class="shopping-name" data-action="ingredient" data-id="${id}">${esc(I[id].name)}<small>${esc(I[id].storage)}</small></button><button class="pantry-button ${pantry[id]?'active':''}" data-action="pantry" data-id="${id}">${pantry[id]?'家里已有':'家里有？'}</button></div>`).join('')}</section>`:'';}).join('')}</div><aside class="shopping-aside"><div class="shopping-tip">${icon('leaf')}<h3>先看看冰箱，再逛菜场。</h3><p>标记家里已有的食材，少买一点重复，多留一点新鲜。</p><div class="tip-line"></div><h4>把新鲜分批带回家</h4><p>叶菜优先安排在前几天；鲜肉及时分装冷藏或冷冻。熟食及时浅盒分装冷藏，不必等彻底放凉；充分加热后再吃。</p></div><details class="budget-card"><summary><span>${icon('bag')} 参考预算摘要</span>${icon('down')}</summary><div><p>${Object.hasOwn(state.budget,p.id)?'已记录的实际采购总花费':'待买食材的双人参考合计'}</p><strong>¥ ${Object.hasOwn(state.budget,p.id)?Number(state.budget[p.id]).toFixed(2):Math.round(estimateCost(p))}</strong><small>${esc(D.meta?.priceNote||'基于演示参考价格和内部份量模型估算，不是四川实时菜价；已有食材不计入，实际花费按采购结算。')}</small><button class="text-link" data-action="edit-budget">记录实际总花费 ${icon('chevron')}</button></div></details><div class="gentle-note">${icon('info')} 使用量与购买量在内部区分；页面按你的习惯省略克重和单价。</div></aside></div>`;}
function aggregate(p){return N.planAmounts(p);}
function estimateCost(p){return N.estimateCost(p,state.pantry[p.id]||{});}

function showModal(html,wide=false,stack=false){const existing=$('.modal'),active=document.activeElement,oldScroll=existing?.scrollTop||0,oldTitle=$('#modal-title')?.textContent,focus={id:active?.id,action:active?.dataset?.action,count:active?.dataset?.count,mode:active?.dataset?.mode};if(stack&&existing)modalHistory.push({html:existing.innerHTML,wide:existing.classList.contains('modal-wide'),scroll:oldScroll});else if(!stack)modalHistory=[];if(!existing)focusBefore=active;const contents=`<div class="modal-tools"><span class="sheet-grabber"></span>${modalHistory.length?`<button class="modal-back icon-button" data-action="modal-back" aria-label="返回上一级">${icon('chevron')}</button>`:''}<button class="modal-close icon-button" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div>${html}`;if(existing){existing.classList.toggle('modal-wide',wide);existing.innerHTML=contents;existing.scrollTop=!stack&&oldTitle===$('#modal-title')?.textContent?oldScroll:0;}else $('#overlay-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title">${contents}</section></div>`;document.body.classList.add('modal-open');requestAnimationFrame(()=>{let target;if(existing&&!stack&&oldTitle===$('#modal-title')?.textContent){target=focus.id?document.getElementById(focus.id):[...document.querySelectorAll('.modal [data-action]')].find(el=>el.dataset.action===focus.action&&el.dataset.count===focus.count&&el.dataset.mode===focus.mode);}target=target||$('.modal input, .modal button:not(.modal-close):not(.modal-back), .modal-close');target?.focus({preventScroll:true});});}
function closeModal(){const el=focusBefore;$('#overlay-root').innerHTML='';document.body.classList.remove('modal-open');modalBack=null;swapContext=null;modalHistory=[];if(el?.isConnected)el.focus();else $('#main-content')?.focus();}
function detailRecipe(id){const r=R[id];if(!r)return;const n=N.recipe(id,2);showModal(`<div class="detail-hero"><div class="recipe-photo-stage"><div class="recipe-photo-panel cooked-panel" ${photoMode==='cooked'?'':'hidden'}>${recipeVisual(r)}</div><div class="recipe-photo-panel raw-panel" ${photoMode==='raw'?'':'hidden'}>${rawRecipeVisual(r)}</div></div><div class="photo-segment" aria-label="查看成品或食材"><button class="${photoMode==='cooked'?'active':''}" data-action="photo-mode" data-mode="cooked" data-id="${id}">成品效果</button><button class="${photoMode==='raw'?'active':''}" data-action="photo-mode" data-mode="raw" data-id="${id}">食材搭配</button></div><span class="detail-kicker">川渝家常 · 两人份做法</span><h2 id="modal-title">${esc(r.name)}</h2><p>${esc(r.benefit)}</p><div class="tags">${tags(r)}</div></div><div class="detail-content"><p class="cooked-disclaimer">成品图根据家常做法与公开资料生成，实际摆盘会随烹调变化。</p><h3>这道菜的食材搭配</h3><div class="detail-ingredient-list">${r.ingredients.filter(x=>I[x.id]).map(x=>`<button data-action="ingredient" data-id="${x.id}">${picture(x.id)}<span>${esc(I[x.id].name)}<small>${esc(I[x.id].role)}</small></span>${icon('chevron')}</button>`).join('')}</div>${r.allergies?.length?`<p class="allergy-note">包含：${r.allergies.map(esc).join('、')}。有过敏情况时请替换对应食材。</p>`:''}<div class="pairing-callout">${icon('leaf')}<div><h3>为什么这样搭</h3><p>${esc(r.pairing)}</p></div></div><h3>熟悉厨房的你，可以这样做</h3><ol class="cooking-steps">${r.steps.map((s,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(s)}</p></li>`).join('')}</ol><div class="storage-callout">${icon('clock')}<div><h4>做完之后</h4><p>${esc(r.storage)}</p></div></div><details class="nutrition-details"><summary>双人配方克重与营养估算 ${icon('down')}</summary><p>本菜配方为 <strong>2 人份</strong>。鲜原料按可食部生重、米和木耳按干重，熟花生按直接食用重量记录。每人参考量按均分双人配方计算，不代表一餐或全天摄入。</p>${gramsTable(n.rows)}<h4>每人均分的营养参考</h4>${nutritionValues(n.perPerson)}<details class="pair-total"><summary>查看本菜双人营养合计 ${icon('down')}</summary>${nutritionValues(n.total)}</details><small>营养参考值 × 本表原料克数 ÷ 100，再逐项相加。单人参考值为双人合计的一半。${esc(D.meta.dataNote)}</small></details><button class="button secondary full" data-action="favorite-detail" data-id="${id}">${icon('heart')} ${state.favorites.includes(id)?'已收藏 · 点击取消':'收藏这道家常灵感'}</button></div>`,false,true);}
function detailIngredient(id){const i=I[id];if(!i)return;showModal(`<div class="ingredient-detail-top">${picture(id)}<span class="eyebrow">${categoryName(i.category)}</span><h2 id="modal-title">${esc(i.name)}</h2><p>${esc((i.alias||[]).length?'本地叫法：'+i.alias.join(' / '):'川渝日常食材')}</p></div><div class="detail-content"><div class="ingredient-role"><span>${icon('leaf')}</span><div><h3>${esc(i.role)}</h3><p>${esc(i.benefit)}</p></div></div><div class="info-row"><h4>挑选与品种</h4><p>${esc(i.selection)}</p></div><div class="info-row"><h4>新鲜怎么留</h4><p>${esc(i.storage)}</p></div><div class="info-row"><h4>应季参考</h4><p>${esc(i.season)}</p></div><h3>把它端上餐桌</h3><div class="ingredient-recipe-links">${D.recipes.filter(r=>r.ingredients.some(x=>x.id===id)).slice(0,5).map(r=>`<button data-action="recipe" data-id="${r.id}">${esc(r.name)}${icon('arrow')}</button>`).join('')||(i.category==='fruit'?'<p>作为每日水果单独安排，吃完整水果优先于果汁。</p>':'<p>当前菜库暂未收录这一食材的专属配方；可参考上面的品种、搭配作用与储存说明。</p>')}</div><small class="muted">图像为 AI 生成的代表性食材；具体品种识别请结合名称与挑选说明，不以图像作为唯一依据。</small></div>`,false,true);}
function detailScience(id){const s=D.science.find(s=>s.id===id);if(!s)return;showModal(`<div class="science-detail-header"><span>${icon('spark')}</span><span class="eyebrow">科学结论 · 日常建议</span><h2 id="modal-title">${esc(s.title)}</h2><p>${esc(s.summary)}</p></div><div class="detail-content"><h3>把道理说得简单一点</h3><p class="reading-text">${esc(s.explanation)}</p><div class="pairing-callout"><span>${icon('leaf')}</span><div><h3>用在今天的餐桌上</h3>${(Array.isArray(s.advice)?s.advice:[s.advice]).map(a=>`<p>${esc(a)}</p>`).join('')}</div></div><h3>参考来源</h3>${sourcesHTML(s.sourceIds)}<p class="scope-note">食间规划的是午餐、晚餐与水果。早餐、零食、饮品与实际份量同样影响全天摄入；如有特殊营养需求，请咨询专业人士。</p></div>`);}
function sourcesHTML(ids){return D.sources.filter(s=>!ids||ids.includes(s.id)).map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(s.title)}<small>${esc(s.note||'权威资料')} · 更新/核对 ${esc(s.updated||'2026-10-11')}</small></span>${icon('arrow')}</a>`).join('');}
function sourcesModal(){showModal(`<div class="modal-heading"><span class="eyebrow">透明的内容依据</span><h2 id="modal-title">来源与数据说明</h2><p>能查到的依据，以及仍然需要校对的部分。</p></div><div class="detail-content">${sourcesHTML()}<div class="pairing-callout"><div><h3>营养数据</h3><p>${esc(D.meta?.dataNote||'食材每 100g 营养值为原型参考估算，尚未逐项核对中国食物成分表。不用于精确个体营养处方。')}</p><h3>价格与预算</h3><p>${esc(D.meta?.priceNote||'价格为演示估算，不是四川实时菜价。实际采购重量会参考可食部，仍受包装、份量和采购渠道影响。')}</p><h3>图像来源</h3><p>食材图与成品图由 AI 生成，立体餐盘为 WebGL 几何示意。前者展示家常菜的外观，后者帮助理解一餐搭配；实际摆盘与品种请结合文字判断。</p></div></div></div>`);}
function generateDays(count,mode=state.preferences.defaultMealMode){
 const shuffle=a=>a.map(v=>[v,Math.random()]).sort((a,b)=>a[1]-b[1]).map(x=>x[0]);
 const recent=state.plans.slice(-2).flatMap(p=>p.days.flatMap(d=>mealKinds(p).map(k=>d[k]?.main).filter(Boolean)));
 let pool=shuffle(D.recommendedMeals||[]),usedMain=new Set(),usedVeg={},usedStaple={},meals=[];
 for(let n=0;n<count*mealKinds(mode).length;n++){const unused=pool.filter(m=>!usedMain.has(m.main));const candidates=unused.length?unused:pool;
 candidates.sort((a,b)=>((usedVeg[a.veg]||0)+(usedStaple[a.staple]||0)*.4+(recent.includes(a.main)?.2:0))-((usedVeg[b.veg]||0)+(usedStaple[b.staple]||0)*.4+(recent.includes(b.main)?.2:0)));
 const m=candidates[0];meals.push({main:m.main,veg:m.veg,staple:m.staple});usedMain.add(m.main);usedVeg[m.veg]=(usedVeg[m.veg]||0)+1;usedStaple[m.staple]=(usedStaple[m.staple]||0)+1;
 }
 return Array.from({length:count},(_,i)=>(mode==='dinner'?{dinner:meals[i],fruit:null}:{lunch:meals[i*2],dinner:meals[i*2+1],fruit:null}));
}
function openWizard(future=false){let start=today();if(future&&state.plans.length){const latest=[...state.plans].sort((a,b)=>addDate(b.start,b.days.length-1).localeCompare(addDate(a.start,a.days.length-1)))[0];start=addDate(latest.start,latest.days.length);if(start<today())start=today();}wizard={start,count:5,days:null,mealMode:state.preferences.defaultMealMode};wizardRender();}
function wizardRender(){const w=wizard;showModal(`<div class="modal-heading"><span class="eyebrow">先选时间，再选你们想吃的</span><h2 id="modal-title">把接下来几天，搭成喜欢的样子</h2><p>需要安排的每一餐都能主动选。水果留给你，食间不会自动填入。</p></div><div class="wizard-body"><label class="field-label" for="start-date">从哪一天开始？</label><input class="date-input" id="start-date" type="date" value="${w.start}" required>${modeControl(w.mealMode,'wizard-mode')}<p class="field-label">想安排几天？</p><div class="duration-pills">${[3,4,5,6,7].map(n=>`<button class="${n===w.count?'active':''}" data-action="duration" data-count="${n}">${n} 天</button>`).join('')}</div><div class="wizard-included"><span>${icon('people')} 两人家常</span><span>${icon('sun')} ${scopeLabel(w)}</span><span>${icon('leaf')} 水果自己选</span></div><p id="wizard-error" class="form-error" role="alert"></p><button class="button primary full" data-action="start-builder" data-mode="manual">自己选菜，从空餐盘开始 ${icon('arrow')}</button><button class="button secondary full auto-start" data-action="start-builder" data-mode="recommended">${icon('spark')} 先推荐正餐，我再调整</button><small class="wizard-note">两种方式都可自由调整；水果必须由你选择后再保存。</small></div>`);wizard=w;}
function overlaps(start,count,excludeId=null){const end=addDate(start,count-1);return state.plans.some(p=>p.id!==excludeId&&start<=addDate(p.start,p.days.length-1)&&end>=p.start);}
function builder(){const w=wizard||draft;if(!w){view='home';return home(getPlan());}wizard=w;const index=w.index||0,d=w.days[index],missing=missingDraft(w),complete=w.days.filter(day=>draftCompleteDay(day,w)).length;return `<div class="builder-heading"><button class="text-link" data-action="exit-builder">${icon('chevron')} 返回首页 · 草稿自动保存</button><div class="page-intro"><div><span class="eyebrow">YOUR TABLE, YOUR CHOICE</span><h1>今天的餐桌，你来做主。</h1><p>${dateText(w.start)} 起 · ${w.days.length} 天 · ${scopeLabel(w)}与水果由你搭配</p></div><button class="button secondary" data-action="recommend-draft">${icon('spark')} 推荐未选的正餐</button></div></div>${modeControl(w.mealMode,'builder-mode')}<div class="day-strip builder-days" role="tablist" aria-label="选择要搭配的日期">${w.days.map((day,i)=>`<button role="tab" aria-selected="${i===index}" class="day-tab ${i===index?'selected':''}" data-action="builder-day" data-index="${i}"><span>${weekday(addDate(w.start,i))}${draftCompleteDay(day,w)?icon('check'):''}</span><strong>${dateText(addDate(w.start,i))}</strong><small>${day.fruit?'水果已选':'待选水果'}</small></button>`).join('')}</div><div class="builder-workspace"><div class="builder-meals ${w.mealMode==='dinner'?'dinner-only':''}">${mealKinds(w).map(kind=>builderMeal(kind,d[kind])).join('')}</div><aside class="builder-aside"><section class="builder-fruit"><span class="eyebrow">一份清甜，由你决定</span><h3>今天的水果</h3><button class="builder-fruit-select ${d.fruit?'has-fruit':''}" data-action="draft-fruit">${d.fruit?picture(d.fruit):`<span class="fruit-empty-illustration">${icon('leaf')}<i>＋</i></span>`}<strong>${d.fruit?esc(I[d.fruit].name):'还没选水果'}</strong><span>${d.fruit?'点击换一种喜欢的水果':'点击，挑一份今天喜欢的清甜'}</span>${icon('down')}</button>${d.fruit?`<button class="text-link" data-action="ingredient" data-id="${d.fruit}">认识这份水果 ${icon('arrow')}</button>`:'<p class="fruit-manual-note">水果不会自动生成。<br>你选过的，才会放进这份菜单。</p>'}</section><section class="builder-progress"><div class="progress-heading"><span>这份菜单的进度</span><strong>${complete}<small> / ${w.days.length} 天</small></strong></div><div class="progress-track"><i style="width:${complete/w.days.length*100}%"></i></div><p>${missing?`还有 ${missing} 处待选择，慢慢挑，选好再保存。`:'每一天都选好了，可以安心保存。'}</p><button class="button primary full" data-action="save-plan" ${missing?'disabled':''}>${icon('check')} ${w.editId?'保存本周期调整':'保存我的菜单'}</button><p id="builder-error" class="form-error" role="alert"></p></section><div class="builder-tip">${icon('leaf')}<p>蔬菜约半盘，主食与蛋白质菜各约四分之一。点成品看做法，点食材了解它的作用。</p></div></aside></div>`;}
function builderMeal(kind,m){return `<section class="builder-meal" data-kind="${kind}"><div class="meal-title"><span class="meal-icon ${kind}">${icon(kind==='lunch'?'sun':'moon')}</span><div><h3>${kind==='lunch'?'午餐':'晚餐'}</h3><span>把喜欢的家常味，搭成一餐</span></div><span class="meal-ready">${['main','veg','staple'].filter(s=>m[s]).length}/3</span></div><div class="builder-plate-stage">${plateVisual(m,'builder-plate')}<span class="plate-note">${icon('bowl')} 立体餐桌 · 拖动旋转，点击已选菜品</span></div><div class="builder-slot-list">${['main','veg','staple'].map(slot=>`<div class="builder-slot ${m[slot]?'filled':''}"><button data-action="draft-slot" data-kind="${kind}" data-slot="${slot}">${m[slot]?cooked(m[slot]):`<span class="slot-empty">${icon(slot==='veg'?'leaf':'plus')}</span>`}<span><small>${{main:'蛋白质菜',veg:'蔬菜',staple:'主食'}[slot]}</small><strong>${m[slot]?esc(R[m[slot]].name):`选择${{main:'一道蛋白质菜',veg:'一道蔬菜',staple:'饭或粥'}[slot]}`}</strong></span>${icon(m[slot]?'refresh':'plus')}</button>${m[slot]?`<button class="slot-info" data-action="recipe" data-id="${m[slot]}" aria-label="查看${esc(R[m[slot]].name)}的做法">${icon('info')}</button>`:''}</div>`).join('')}${m.soup?`<div class="builder-slot filled"><button data-action="draft-slot" data-kind="${kind}" data-slot="soup">${cooked(m.soup)}<span><small>附加汤羹</small><strong>${esc(R[m.soup].name)}</strong></span>${icon('refresh')}</button><button class="slot-info" data-action="draft-remove-soup" data-kind="${kind}" aria-label="移除汤羹">${icon('close')}</button></div>`:`<button class="meal-soup-link" data-action="draft-slot" data-kind="${kind}" data-slot="soup">${icon('plus')} 再添一道汤（可选）</button>`}</div>${m.main?ingredientChips(R[m.main],4):'<div class="empty-dish-note">先选菜，再看看食材之间的搭配。</div>'}</section>`;}
function swapModal(kind,slot,target='plan'){const index=target==='draft'?(wizard.index||0):dayIndex;swapContext={kind,slot,target,index};pickerQuery='';pickerRender();}
function pickerRender(){const c=swapContext,m=c.target==='draft'?wizard.days[c.index][c.kind]:getPlan().days[c.index][c.kind],current=m[c.slot],list=D.recipes.filter(r=>r.type===c.slot&&(!pickerQuery||[r.name,...r.ingredients.map(x=>I[x.id].name)].join(' ').includes(pickerQuery)));const html=`<div class="modal-heading"><span class="eyebrow">${c.kind==='lunch'?'午餐':'晚餐'} · 你喜欢的家常味</span><h2 id="modal-title">挑${{main:'一道蛋白质菜',veg:'一道蔬菜',staple:'一份饭或粥',soup:'一道汤羹'}[c.slot]}</h2><p>先看成品，再选想吃的。食材名称也可以点开认识。</p></div><div class="picker-toolbar"><label class="search-box">${icon('search')}<input id="picker-search" type="search" placeholder="搜索菜名或食材" aria-label="搜索可选菜品" value="${esc(pickerQuery)}"></label></div><div class="dish-picker-grid">${list.map(r=>`<article class="dish-choice ${r.id===current?'selected':''}"><button class="dish-choice-visual" data-action="choose-swap" data-id="${r.id}" aria-label="选择${esc(r.name)}">${recipeVisual(r)}${r.id===current?`<span class="choice-check">${icon('check')}</span>`:''}</button><div class="dish-choice-body"><button class="dish-choice-name" data-action="choose-swap" data-id="${r.id}">${esc(r.name)}${icon(r.id===current?'check':'plus')}</button><p>${esc(r.benefit)}</p>${ingredientChips(r,2)}<button class="text-link" data-action="recipe" data-id="${r.id}">看看做法 ${icon('arrow')}</button></div></article>`).join('')}</div>${!list.length?'<div class="no-results">试试“鸡”或“豆腐”，换个关键词看看。</div>':''}`;showModal(html,true);swapContext=c;}
function fruitModal(target='plan'){fruitApplyAll=false;swapContext={target,slot:'fruit',index:target==='draft'?(wizard.index||0):dayIndex};const c=swapContext,current=target==='draft'?wizard.days[c.index].fruit:getPlan().days[c.index].fruit;showModal(`<div class="modal-heading"><span class="eyebrow">不替你决定，留给你喜欢的清甜</span><h2 id="modal-title">今天想吃哪种水果？</h2><p>完整水果优先，按照季节和手边的食材自己选择。</p></div><div class="fruit-options">${D.ingredients.filter(i=>i.category==='fruit').map(i=>`<div class="fruit-choice ${i.id===current?'selected':''}"><button data-action="choose-fruit" data-id="${i.id}" aria-label="选择${esc(i.name)}">${picture(i.id)}<strong>${esc(i.name)}</strong><small>${esc(i.season)}</small>${i.id===current?icon('check'):''}</button><button class="fruit-learn" data-action="ingredient" data-id="${i.id}">认识它 ${icon('info')}</button></div>`).join('')}</div>${target==='draft'?`<label class="fruit-apply-all"><input id="fruit-all-days" type="checkbox"><span>这几天都选同一种水果<small>勾选后，把你点击的水果安排到本周期每一天</small></span></label>`:''}`);swapContext=c;}

function settings(){let recovery=rawBackup;try{recovery=recovery||localStorage.getItem(KEY+':recovery');}catch{}showModal(`<div class="modal-heading"><span class="eyebrow">你的菜单，由你保管</span><h2 id="modal-title">本地数据与设置</h2><p>菜单、收藏与准备状态存储在当前浏览器。</p></div><div class="detail-content">${modeControl(state.preferences.defaultMealMode,'default-mode','新建菜单默认安排')}<p class="settings-mode-note">默认午餐＋晚餐。只安排晚餐时，午餐不参与选菜、采购或营养汇总；已保存周期保留自己的设置，编辑周期时可另行切换。</p><div class="data-stats"><span><strong>${state.plans.length}</strong>份计划</span><span><strong>${state.favorites.length}</strong>道收藏</span></div><button class="settings-row" data-action="export">${icon('download')}<span>导出菜单备份<small>保存为 JSON 文件，方便迁移浏览器</small></span>${icon('chevron')}</button>${recovery?`<button class="settings-row" data-action="export-recovery">${icon('download')}<span>下载读取失败的原始备份<small>保留原文件内容，方便修复与恢复</small></span>${icon('chevron')}</button>`:''}<button class="settings-row" data-action="import">${icon('upload')}<span>导入菜单备份<small>格式验证后再确认替换当前数据</small></span>${icon('chevron')}</button><button class="settings-row" data-action="sources">${icon('book')}<span>来源与数据说明<small>营养估算、价格和图像的使用边界</small></span>${icon('chevron')}</button><div class="scope-note">本机储存按网址区分。本地预览与线上地址不会自动共享数据；更换设备或清理浏览器前，请先导出备份。食间不记录身体指标，也不将菜单发送给其他用户。</div><button class="settings-row danger" data-action="reset-confirm">${icon('trash')}<span>清空本机数据<small>将删除所有菜单、收藏和勾选记录</small></span>${icon('chevron')}</button></div>`);}
function exportData(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`食间-菜单备份-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('菜单备份已导出');}
function importData(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>2e6)throw Error('文件过大，请使用食间导出的备份');const incoming=validState(JSON.parse(await f.text()));window.__shijianIncoming=incoming;showModal(`<div class="modal-heading"><h2 id="modal-title">替换为这份备份？</h2><p>备份包含 ${incoming.plans.length} 份菜单和 ${incoming.favorites.length} 道收藏。当前本机数据将被替换，请先确认已保留需要的备份。</p></div><div class="confirm-actions"><button class="button secondary" data-action="export">先导出当前数据</button><button class="button primary" data-action="import-confirm">确认导入</button></div>`);}catch(e){toast('导入失败：'+e.message);}};input.click();}
function confirmDelete(id){const p=state.plans.find(p=>p.id===id);showModal(`<div class="modal-heading"><h2 id="modal-title">删除这份计划？</h2><p>${dateText(p.start)}开始的 ${p.days.length} 天菜单将从本机删除。其他计划会保留。</p></div><div class="confirm-actions"><button class="button secondary" data-action="close-modal">保留计划</button><button class="button danger-button" data-action="delete-confirm" data-id="${esc(id)}">删除计划</button></div>`);}
const actions={
'navigate':el=>{view=el.dataset.view;if(view!=='shopping')activePlan=null;if(view!=='shopping')dayIndex=0;if(view==='home'){const p=pickPlan();if(p&&p.start<=today())dayIndex=Math.max(0,Math.floor((new Date(today()+'T12:00:00')-new Date(p.start+'T12:00:00'))/864e5));}render();window.scrollTo({top:0,behavior:'smooth'});},
'new-plan':el=>openWizard(el.dataset.future==='true'),
'day':el=>{dayIndex=Number(el.dataset.index);render('day');},
'open-plan':el=>{activePlan=el.dataset.id;dayIndex=0;view='home';render();window.scrollTo({top:0,behavior:'smooth'});},
'recipe':el=>detailRecipe(el.dataset.id),'ingredient':el=>detailIngredient(el.dataset.id),'science-detail':el=>detailScience(el.dataset.id),'sources':sourcesModal,
'favorite':el=>{const id=el.dataset.id;if(state.favorites.includes(id))state.favorites=state.favorites.filter(x=>x!==id);else state.favorites.push(id);save();render();toast(state.favorites.includes(id)?'已收藏，想吃的时候再翻出来':'已取消收藏');},
'favorite-detail':el=>{actions.favorite(el);el.innerHTML=icon('heart')+' '+(state.favorites.includes(el.dataset.id)?'已收藏 · 点击取消':'收藏这道家常灵感');},
'recipe-filter':el=>{recipeFilter=el.dataset.filter;render();},'ingredient-filter':el=>{ingredientFilter=el.dataset.filter;render();},
'duration':el=>{wizard.count=Number(el.dataset.count);wizard.start=$('#start-date').value;wizardRender();},
 'wizard-mode':el=>{wizard.start=$('#start-date').value;wizard.mealMode=el.dataset.mode;wizardRender();},
 'builder-mode':el=>{wizard.mealMode=el.dataset.mode;wizard.days.forEach(d=>mealKinds(wizard).forEach(k=>d[k]??={main:null,veg:null,staple:null}));saveDraft();render('none');},
 'default-mode':el=>{const prev=state.preferences.defaultMealMode;state.preferences.defaultMealMode=el.dataset.mode;if(!save()){state.preferences.defaultMealMode=prev;return;}document.querySelectorAll('[data-action="default-mode"]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===el.dataset.mode);b.setAttribute('aria-checked',String(b.dataset.mode===el.dataset.mode));if(b.querySelector('.mode-check'))b.querySelector('.mode-check').hidden=b.dataset.mode!==el.dataset.mode;});toast('默认餐次已保存，新建菜单会使用这个设置');},
 'start-builder':el=>{const start=$('#start-date').value;if(!start||addDate(start,0)!==start){$('#wizard-error').textContent='请选择有效的开始日期。';return;}if(overlaps(start,wizard.count)){$('#wizard-error').textContent='这段日期已经有菜单了，换个开始日期再安排。';return;}wizard.start=start;wizard.days=el.dataset.mode==='recommended'?generateDays(wizard.count,wizard.mealMode):Array.from({length:wizard.count},()=>Object.assign({fruit:null},...mealKinds(wizard).map(k=>({[k]:{main:null,veg:null,staple:null}}))));wizard.index=0;saveDraft();closeModal();view='builder';render();window.scrollTo({top:0,behavior:'smooth'});},
 'resume-draft':()=>{if(!draft)return;draft=validDraft(draft);wizard=draft;view='builder';render();window.scrollTo({top:0,behavior:'smooth'});},
 'exit-builder':()=>{saveDraft();view='home';render();window.scrollTo({top:0,behavior:'smooth'});},
 'edit-plan':()=>{const p=getPlan();wizard={start:p.start,count:p.days.length,days:structuredClone(p.days),index:dayIndex,editId:p.id,mealMode:p.mealMode||'both'};saveDraft();view='builder';render();},
 'builder-day':el=>{wizard.index=Number(el.dataset.index);saveDraft();render('day');},
 'draft-slot':el=>swapModal(el.dataset.kind,el.dataset.slot,'draft'),
 'draft-fruit':()=>fruitModal('draft'),
 'draft-remove-soup':el=>{delete wizard.days[wizard.index||0][el.dataset.kind].soup;saveDraft();render('day');},
 'recommend-draft':()=>{const recommended=generateDays(wizard.days.length,wizard.mealMode);wizard.days.forEach((d,i)=>mealKinds(wizard).forEach(k=>['main','veg','staple'].forEach(s=>{if(!d[k][s])d[k][s]=recommended[i][k][s];})));saveDraft();render('day');toast('只补上未选的正餐，水果仍由你选');},
 'save-plan':()=>{if(!wizard?.days)return;if(missingDraft(wizard)){toast('先选好每一天的正餐与水果，再保存');return;}if(wizard.editId&&!state.plans.some(p=>p.id===wizard.editId))wizard.editId=null;if(!wizard.editId&&state.plans.length>=100){$('#builder-error').textContent='本机已保存100个周期。请先导出历史备份并删除不再需要的周期，再保存新菜单。';return;}if(overlaps(wizard.start,wizard.count,wizard.editId)){$('#builder-error').textContent='这段日期已经有其他菜单了，请调整开始日期。';return;}const previous=state;state=structuredClone(state);let p;if(wizard.editId){p=state.plans.find(p=>p.id===wizard.editId);p.days=wizard.days.map(d=>Object.assign({fruit:d.fruit},...mealKinds(wizard).map(k=>({[k]:structuredClone(d[k])}))));p.mealMode=wizard.mealMode;}else {p={id:crypto.randomUUID?.()||'plan-'+Date.now(),start:wizard.start,days:wizard.days.map(d=>Object.assign({fruit:d.fruit},...mealKinds(wizard).map(k=>({[k]:structuredClone(d[k])})))),mealMode:wizard.mealMode,created:Date.now()};state.plans.push(p);}if(!save()){state=previous;$('#builder-error').textContent='正式菜单暂未保存成功，已保留当前草稿。请释放浏览器存储空间后重试，或先导出已有菜单。';return;}activePlan=p.id;dayIndex=wizard.index||0;view='home';wizard=null;draft=null;try{localStorage.removeItem(DRAFT_KEY);}catch{}closeModal();render();toast('菜单已保存，每一餐都是你喜欢的样子');},
 'remove-soup':el=>{delete getPlan().days[dayIndex][el.dataset.kind].soup;save();render('day');toast('汤羹已移除，清单已更新');},
 'swap':el=>swapModal(el.dataset.kind,el.dataset.slot), 'swap-fruit':()=>fruitModal(),
 'choose-swap':el=>{const c=swapContext;if(!c)return;const m=c.target==='draft'?wizard.days[c.index][c.kind]:getPlan().days[c.index][c.kind];m[c.slot]=el.dataset.id;if(c.target==='draft')saveDraft();else save();closeModal();render('day');toast('已经盛上餐盘，点食材还能看介绍');},
 'choose-fruit':el=>{const c=swapContext;if(!c)return;if(c.target==='draft'){if(fruitApplyAll)wizard.days.forEach(d=>d.fruit=el.dataset.id);else wizard.days[c.index].fruit=el.dataset.id;saveDraft();}else {getPlan().days[c.index].fruit=el.dataset.id;save();}closeModal();render('day');toast('水果已按你的选择安排好了');},
 'modal-back':()=>{const prev=modalHistory.pop();if(!prev)return;$('.modal').innerHTML=prev.html;$('.modal').classList.toggle('modal-wide',prev.wide);$('.modal').scrollTop=prev.scroll;if($('#fruit-all-days'))$('#fruit-all-days').checked=fruitApplyAll;$('.modal button')?.focus({preventScroll:true});},
 'photo-mode':el=>{photoMode=el.dataset.mode;$('.cooked-panel').hidden=photoMode!=='cooked';$('.raw-panel').hidden=photoMode!=='raw';document.querySelectorAll('[data-action="photo-mode"]').forEach(button=>{button.classList.toggle('active',button.dataset.mode===photoMode);button.setAttribute('aria-pressed',String(button.dataset.mode===photoMode));});},
'shopping-check':el=>{const p=getPlan();state.checked[p.id]??={};state.checked[p.id][el.dataset.id]=!state.checked[p.id][el.dataset.id];save();render();},
'pantry':el=>{const p=getPlan();state.pantry[p.id]??={};state.pantry[p.id][el.dataset.id]=!state.pantry[p.id][el.dataset.id];save();render();},
'copy-shopping':async()=>{const p=getPlan(),a=aggregate(p),text=`食间 · ${dateText(p.start)}起 ${p.days.length}天两人食\n\n`+['vegetable','protein','grain','fruit','seasoning'].map(c=>{const ids=Object.keys(a).filter(id=>I[id].category===c&&!state.pantry[p.id]?.[id]);return ids.length?categoryName(c)+'\n'+ids.map(id=>(state.checked[p.id]?.[id]?'✓ ':'□ ')+I[id].name).join('\n'):'';}).filter(Boolean).join('\n\n');try{await navigator.clipboard.writeText(text);toast('清单已复制，可以带着去买菜');}catch{showModal(`<div class="modal-heading"><h2 id="modal-title">复制采购清单</h2><p>选择下方文本，手动复制即可。</p></div><textarea class="copy-area" readonly>${esc(text)}</textarea>`);}},
'edit-budget':()=>{const p=getPlan();showModal(`<div class="modal-heading"><h2 id="modal-title">记录这次的实际总花费</h2><p>只记录整份采购的合计，方便回看；清空即可恢复参考估算。</p></div><div class="wizard-body"><label class="field-label" for="budget-input">总花费（元）</label><input class="date-input" id="budget-input" type="number" min="0" max="99999" step="0.01" value="${esc(state.budget[p.id]??'')}" placeholder="输入实际合计"><button class="button primary full" data-action="save-budget">保存记录</button></div>`);},
'save-budget':()=>{const input=$('#budget-input');if(!input.checkValidity()){input.reportValidity();return;}const v=input.value;if(v)state.budget[getPlan().id]=Number(v);else delete state.budget[getPlan().id];save();closeModal();render();toast('预算记录已保存');},
'export-recovery':()=>{let raw=rawBackup;try{raw=raw||localStorage.getItem(KEY+':recovery');}catch{}if(raw){const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='食间-原始记录恢复备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('原始恢复备份已导出');}},'close-modal':closeModal,'settings':settings,'export':exportData,'import':importData,
'import-confirm':()=>{if(!window.__shijianIncoming)return;state=window.__shijianIncoming;delete window.__shijianIncoming;activePlan=null;save();closeModal();render();toast('备份已导入');},
'delete-plan':el=>confirmDelete(el.dataset.id),'delete-confirm':el=>{const id=el.dataset.id;state.plans=state.plans.filter(p=>p.id!==id);delete state.checked[id];delete state.pantry[id];delete state.budget[id];if(activePlan===id)activePlan=null;save();closeModal();render();toast('计划已删除');},
'reset-confirm':()=>showModal(`<div class="modal-heading"><h2 id="modal-title">清空所有本机记录？</h2><p>菜单、收藏和食材准备状态会被删除。建议先导出备份。</p></div><div class="confirm-actions"><button class="button secondary" data-action="export">先导出备份</button><button class="button danger-button" data-action="reset">确认清空</button></div>`),
'reset':()=>{draft=null;wizard=null;try{localStorage.removeItem(DRAFT_KEY);}catch{}state=defaultState();activePlan=null;dayIndex=0;rawBackup=null;try{localStorage.removeItem(KEY+':recovery');}catch{}save();closeModal();render();toast('本机记录已清空');},
 'toggle-sort':el=>{const panel=el.nextElementSibling;panel.hidden=!panel.hidden;el.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)panel.querySelector('button')?.focus();},
 'sort':el=>{recipeSort=el.dataset.sort;render();}
};
document.addEventListener('shijian-dish-open',e=>{if(R[e.detail?.id])detailRecipe(e.detail.id);else{const kind=e.target.closest('.builder-meal')?.dataset.kind;if(kind&&['main','veg','staple'].includes(e.detail?.slot))swapModal(kind,e.detail.slot,'draft');}});
window.addEventListener('shijian-scene-ready',()=>window.SHJ_SCENE?.mountAll());
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();actions[el.dataset.action]?.(el);}else if(e.target.classList.contains('modal-backdrop'))closeModal();if(!e.target.closest('.custom-select')){document.querySelectorAll('.select-options').forEach(p=>p.hidden=true);document.querySelectorAll('.sort-trigger').forEach(p=>p.setAttribute('aria-expanded','false'));}});
document.addEventListener('change',e=>{if(e.target.id==='fruit-all-days')fruitApplyAll=e.target.checked;});
document.addEventListener('input',e=>{if(e.target.id==='picker-search'){const pos=e.target.selectionStart;pickerQuery=e.target.value;pickerRender();$('#picker-search').focus();$('#picker-search').setSelectionRange(pos,pos);return;}if(e.target.id==='recipe-search'||e.target.id==='ingredient-search'){const id=e.target.id,pos=e.target.selectionStart,v=e.target.value;if(id==='recipe-search')recipeQuery=v;else ingredientQuery=v;render('none');const input=$('#'+id);input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.target.closest('.meal-mode-segment')&&['ArrowRight','ArrowDown','ArrowLeft','ArrowUp'].includes(e.key)){e.preventDefault();const radios=[...e.target.closest('.meal-mode-segment').querySelectorAll('[role=radio]')],i=radios.indexOf(e.target),next=radios[(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+radios.length)%radios.length];next?.focus({preventScroll:true});next?.click();return;}if(e.key==='Escape'){if($('.modal'))closeModal();else {document.querySelectorAll('.select-options').forEach(p=>p.hidden=true);$('.sort-trigger')?.setAttribute('aria-expanded','false');}}const modal=$('.modal');if(e.key==='Tab'&&modal){const items=[...modal.querySelectorAll('button,input,textarea,summary,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.target.closest('.select-options')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const items=[...e.target.closest('.select-options').querySelectorAll('button')],i=items.indexOf(document.activeElement);items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length].focus();}});
window.addEventListener('storage',e=>{if(e.key===KEY){try{state=e.newValue?validState(JSON.parse(e.newValue)):defaultState();closeModal();render();toast('另一标签页的菜单已同步');}catch{toast('另一标签页的数据无法读取，请保留备份');}}});
const p=pickPlan();if(p&&p.start<=today())dayIndex=Math.min(p.days.length-1,Math.max(0,Math.floor((new Date(today()+'T12:00:00')-new Date(p.start+'T12:00:00'))/864e5)));
render();
})();
